css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .74); height: var(--loader-size); position: relative; }
.loader .tube { position: absolute; left: 26%; right: 26%; bottom: 2%; height: 62%; border-radius: 3px 3px 8px 8px; overflow: hidden; background: color-mix(in srgb, var(--accent-2) 18%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent); }
.loader .tube::after { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 34%; background: repeating-linear-gradient(color-mix(in srgb, var(--accent) 50%, transparent) 0 2px, transparent 2px 14%); }
.loader .water { position: absolute; left: 0; right: 0; bottom: 0; height: 4%; background: linear-gradient(var(--accent-2), var(--accent)); animation: gauge-fill calc(var(--loader-speed) * 4) ease-in-out infinite; }
.loader i { position: absolute; top: 0; width: 8%; height: 13%; border-radius: 50% 50% 50% 50% / 66% 66% 34% 34%; background: var(--accent-2); animation: gauge-rain calc(var(--loader-speed) * 1.1) linear infinite; }
.loader i:nth-of-type(1) { left: 18%; }
.loader i:nth-of-type(2) { left: 40%; animation-delay: calc(var(--loader-speed) * .28); }
.loader i:nth-of-type(3) { left: 62%; animation-delay: calc(var(--loader-speed) * .55); }
.loader i:nth-of-type(4) { left: 48%; animation-delay: calc(var(--loader-speed) * .82); }
@keyframes gauge-fill { 0%, 6% { height: 4%; } 74%, 88% { height: 92%; } 98%, 100% { height: 4%; } }
@keyframes gauge-rain { 0% { opacity: 0; transform: translateY(0); } 12% { opacity: 1; } 88% { opacity: 1; } 100% { opacity: 0; transform: translateY(280%); } }
